items=[dict(id='cyber',topic_id='mistral-large4-cyber-oct2026',composition='CyberDoor2026',slug='ai-mencari-celah-aplikasi',title='Siapa yang Menemukan Celah Aplikasimu Lebih Dulu?',editorial_slot='tren_2026',source='https://mistral.ai/news/mistral-large-4/',sourceDate='2026-10-06',eventDate='2026-10-06',eventDescription='Public preview Mistral Large4 diperkenalkan6Oktober2026. Liputan Reuters29Oktober melaporkan rilis publik; video hanya mengklaim pengenalan Oktober dan tujuan kemampuan, tidak mengklaim status bobot terbaru.',additionalSources=['https://docs.mistral.ai/models/mistral-large-4-0'],trendEvidence=[dict(url='https://www.reuters.com/legal/litigation/mistral-ai-publicly-releases-large-4-targets-cybersecurity-users-2026-10-29/',date='2026-10-29',basis='Liputan rilis publik dan fokus keamanan siber dalam hasil pencarian.'),dict(url='https://www.lemonde.fr/en/economy/article/2026/10/06/mistral-ai-unveils-new-ai-model-aimed-at-narrowing-the-gap-with-top-chinese-competitors_6758318_19.html',date='2026-10-06',basis='Liputan independen pengenalan model; bukan klaim viral.')],channel='TREN 2026 / AI KEAMANAN',sourceLabel='Mistral • 6 Okt 2026',category='perkembangan2026',relevance='Peluncuran besar Oktober, liputan independen6dan29Oktober; sudut defensif mencari dan memperbaiki celah.',limit='Alur kerja ilustratif • hasil AI tetap perlu diuji.',accuracyNote='Kemampuan pencarian/perbaikan celah dijelaskan vendor dan dalam evaluasi tertentu. Tidak memuat angka benchmark, klaim paling aman, bebas salah, atau ketersediaan bobot tanpa verifikasi.',titles=['Ada celah.\nSiapa menemukannya?','01 / AI ikut mencari\nmasalah keamanan.','02 / Tandai. Perbaiki.\nLalu uji lagi.','03 / Saran AI\nbelum tentu benar.','Tutup celahnya.\nPeriksa perbaikannya.'],recap=[['CARI','BAGIAN MENCURIGAKAN'],['UJI','USULAN PERBAIKAN'],['TINJAU','HASIL OLEH TIM']],closing='Celah ditemukan.\nSudah ditutup?',pill='PERTAHANAN PERANGKAT LUNAK',lines=[['Kalau aplikasimu punya celah,','siapa yang menemukannya dulu?'],['Coba anggap kodenya seperti rumah.','Mistral Large empat, diperkenalkan Oktober,','antara lain ditujukan membantu menemukan dan memperbaiki celah perangkat lunak.'],['Kita tandai bagian mencurigakan,','lihat usulan perbaikannya, lalu jalankan pengujian.','Ini gambaran alur kerja, bukan hasil pemindaian aplikasi sungguhan.'],['Tapi pintu yang terlihat tertutup','belum tentu terkunci.','Saran AI bisa keliru, jadi tim tetap perlu memeriksa dan menguji ulang.'],['Yang dicari bukan sekadar jawaban cepat,','tetapi perbaikan yang terbukti bekerja.','Simpan sebelum mengandalkan pemeriksaan otomatis.']],caption='AI dapat membantu menemukan dan memperbaiki celah, tetapi saran tetap perlu diperiksa dan diuji. Mistral Large4 diperkenalkan Oktober2026; visual hanya alur konseptual defensif. #AI #KeamananDigital'),
dict(id='tap',topic_id='android-tap-to-share-2026',composition='TapShare2026',slug='kirim-foto-dekatkan-ponsel',title='Kirim Foto Cukup Dekatkan Ponsel, Tapi Tetap Perlu Persetujuan',editorial_slot='kehidupan_sehari_hari',source='https://blog.google/products-and-platforms/platforms/android/tap-to-share-android/',sourceDate='2026-08-12',eventDate='2026-08-12',eventDescription='Tap to share diumumkan12Agustus2026 mulai Pixel. Bantuan resmi saat verifikasi menyebut Pixel6+ dengan Android17+; tidak mengklaim semua Android mendukung.',additionalSources=['https://support.google.com/android/answer/17161144'],channel='SEHARI-HARI / BERBAGI FILE',sourceLabel='Google • 12 Agu 2026',category='perkembangan2026',relevance='Masalah sehari-hari mencari kontak untuk mengirim foto; fitur tap baru2026 dengan persyaratan perangkat yang jelas.',limit='UI konseptual • Pixel 6+ / Android 17+ sesuai bantuan.',accuracyNote='Untuk foto, buka menu Bagikan lalu dekatkan bagian atas kedua ponsel terbuka; perangkat penerima menyetujui. Kontak dapat dipilih bidangnya. Work Profile tidak didukung; tidak menjanjikan kompatibilitas semua Android.',titles=['Mau kirim foto?\nDekatkan ponselnya.','01 / Pilih foto.\nBuka menu Bagikan.','02 / Dekatkan bagian\natas kedua ponsel.','03 / Penerima\ntetap menyetujui.','Praktis berbagi.\nTetap cek penerima.'],recap=[['PILIH','FILE YANG DIKIRIM'],['DEKATKAN','PONSEL TERBUKA'],['SETUJUI','DI PERANGKAT TUJUAN']],closing='Sudah dekat.\nPastikan orangnya tepat.',pill='TAP TO SHARE • FITUR 2026',lines=[['Mau kirim foto ke teman?','Coba dekatkan ponselnya.'],['Bukan asal menempel.','Pada perangkat yang mendukung, fitur tap di Quick Share','dimulai dengan memilih foto dan membuka menu Bagikan.'],['Sekarang dekatkan bagian atas','kedua ponsel yang terbuka, sampai menyala.','Penerima tetap perlu menerima permintaan berbagi; file tidak langsung dikirim sembarangan.'],['Ada syaratnya: panduan Google menyebut','Pixel enam ke atas dengan Android tujuh belas.','Jadi, jangan berharap semua Android langsung bisa.'],['Saat bertukar foto nanti,','cek dukungan perangkat dan pastikan penerimanya benar.','Praktis, tapi tetap kamu yang menentukan.']],caption='Tap to share memudahkan kirim foto setelah memilih Bagikan dan mendekatkan bagian atas ponsel terbuka. Penerima tetap menyetujui. Bantuan Google menyebut Pixel6+/Android17+, bukan seluruh Android. #Android #TipsTeknologi'),
dict(id='gut',topic_id='biosenter-preclinical-2026',composition='GutRobot2026',slug='robot-lentur-menjelajah-usus',title='Robot Lentur Menelusuri Belokan Usus',editorial_slot='eksplorasi_teknologi',source='https://www.utsouthwestern.edu/newsroom/articles/year-2026/oct-robot-improve-gastroenterologists-diagnosis.html',sourceDate='2026-10-28',eventDate='2026-10-28',eventDescription='Laporan studi praklinis BIOSENTER dan publikasi Science Robotics28Oktober2026. Pengerjaan desain telah berlangsung sebelum2026; bukan klaim ide baru pertama.',additionalSources=['https://news.mit.edu/2026/soft-robot-could-help-doctors-diagnose-treat-small-intestine-disorders-1028','https://doi.org/10.1126/scirobotics.adt2230'],channel='TECH / ROBOT LENTUR',sourceLabel='UT Southwestern • 28 Okt 2026',category='perkembangan2026',relevance='Studi praklinis minggu ini menunjukkan gerak dan intervensi; dapat divisualisasikan dengan mekanisme udara dan selubung kirigami.',limit='Ilustrasi anatomi • praklinis, belum uji manusia.',accuracyNote='Dikendalikan operator/joystick dan tertambat kabel; ruang udara memanjang/membelok, kirigami menambat. Demonstrasi imaging,biopsi,fluid delivery bersifat praklinis. Belum robot bebas otonom atau layanan klinis.',titles=['Belokannya rapat.\nAlatnya bagaimana?','01 / Tubuh lentur.\nDidorong tekanan udara.','02 / Menambat dulu.\nLalu bergerak maju.','03 / Kamera dan alat\nlewat saluran tengah.','Bisa menjangkau.\nMasih perlu validasi.'],recap=[['LENTUR','RUANG UDARA'],['TAMBAT','SELUBUNG KIRIGAMI'],['KANAL','KAMERA DAN ALAT']],closing='Sulit dijangkau.\nBisa dibantu gerak lentur.',pill='BIOSENTER • STUDI PRAKLINIS',lines=[['Bayangkan alat medis harus melewati','belokan usus yang rapat.'],['Kita ikuti BIOSENTER,','robot lentur yang diuji secara praklinis.','Ruang berisi udara membuat tubuhnya memanjang dan berbelok.'],['Perhatikan selubungnya.','Pola kirigami membantu menambat pada dinding yang licin,','lalu tubuhnya maju bertahap, diarahkan operator melalui pengendali.'],['Saluran di tengah membawa alat','untuk melihat, mengambil sampel jaringan, atau mengalirkan cairan.','Kemampuan itu didemonstrasikan dalam pengujian praklinis.'],['Jadi, bukan robot bebas berkeliaran di tubuhmu.','Masih perlu pengembangan dan validasi','sebelum diuji pada manusia.']],caption='BIOSENTER memakai tubuh pneumatik dan selubung kirigami untuk menavigasi usus dalam studi praklinis. Operator mengendalikannya; belum diuji pada manusia atau menjadi alat klinis siap pakai. Laporan28Oktober2026. #Robotika #TeknologiMedis'),
dict(id='hydro',topic_id='autothermal-methane-pyrolysis-2026',composition='HydrogenHeat2026',slug='reaktor-hidrogen-panas-dari-dalam',title='Reaktor Hidrogen Dipanaskan dari Dalam',editorial_slot='eksplorasi_teknologi',source='https://news.stanford.edu/stories/2026/09/sustainable-hydrogen-production-heating-method',sourceDate='2026-09-03',eventDate='2026-09-03',eventDescription='Paper Science dan laporan Stanford3September2026; metode autothermal baru, bukan klaim pirolisis ditemukan2026.',additionalSources=['https://pubmed.ncbi.nlm.nih.gov/42691174/','https://doi.org/10.1126/science.aed4911'],channel='TECH / ENERGI',sourceLabel='Stanford • 3 Sep 2026',category='perkembangan2026',relevance='Riset2026 mengatasi kendala pemanasan reaktor pirolisis, dengan hasil karbon padat; tetap relevan untuk tantangan peningkatan skala.',limit='Diagram konsep • bukan klaim nol emisi siklus hidup.',accuracyNote='Pirolisis memecah metana menjadi hidrogen dan karbon padat. Sebagian hidrogen dibakar di dalam untuk memasok panas; produk samping grafit. Tidak mengklaim nol emisi total, mesin energi abadi, atau industrialisasi sudah tuntas.',titles=['Reaktornya besar.\nPanas susah ke tengah.','01 / Metana dipecah.\nHidrogen dipisahkan.','02 / Sebagian hidrogen\nmenjadi sumber panas.','03 / Karbonnya padat.\nBisa berupa grafit.','Panas dari dalam.\nTantangan belum habis.'],recap=[['METANA','BAHAN MASUK'],['PANAS','DARI DALAM REAKTOR'],['KARBON','PRODUK PADAT']],closing='Letak pemanas\nbisa mengubah proses.',pill='RISET PEMANASAN • 2026',lines=[['Kalau reaktornya besar,','bagaimana panas bisa mencapai tengahnya?'],['Bayangkan memanaskan panci raksasa dari luar.','Pada riset Stanford ini,','metana dipecah menjadi hidrogen dan karbon padat.'],['Lalu kita pindahkan sumber panasnya ke dalam.','Sebagian hidrogen yang dihasilkan dibakar','untuk membantu memasok panas bagi proses berikutnya.'],['Ada bonus: karbon padatnya berupa grafit berkualitas tinggi,','yang berpotensi berguna untuk baterai.','Namun, itu belum berarti seluruh proses bebas emisi.'],['Intinya, bukan energi tanpa habis.','Ini cara memasok panas lebih efektif.','Peningkatan skala dan dampak keseluruhan tetap perlu diperiksa.']],caption='Metode autothermal Stanford memanaskan pirolisis metana dari dalam dengan sebagian hidrogen yang dihasilkan. Menghasilkan karbon padat/grafit; bukan energi abadi atau klaim nol emisi siklus hidup. Riset3September2026. #Energi #Hidrogen'),
dict(id='lunar',topic_id='cerberuz-lunarecycle-2026',composition='LunarRecycle2026',slug='sampah-kemasan-jadi-komponen-bulan',title='Sampah Kemasan Bisa Menjadi Komponen untuk Pangkalan Bulan',editorial_slot='eksplorasi_teknologi',source='https://news.mit.edu/2026/mit-student-team-cerberuz-wins-nasa-lunarecycle-centennial-challenge-1020',sourceDate='2026-10-20',eventDate='2026-08',eventDescription='Demonstrasi final LunaRecycle di Bumi padaAgustus2026 menurut NASA; laporan MIT20Oktober. Tim memenangkan fase1pada2025; tidak diklaim alat sudah beroperasi di Bulan.',additionalSources=['https://www.nasa.gov/prizes-challenges-and-crowdsourcing/centennial-challenges/lunarecycle/'],channel='TECH / DAUR ULANG',sourceLabel='MIT • 20 Okt 2026',category='perkembangan2026',relevance='Hasil demonstrasi kompetisi2026 dan penjelasan mekanisme terbaru Oktober; persoalan pasokan dan limbah pangkalan masa depan.',limit='Konsep pangkalan • demo dilakukan di Bumi.',accuracyNote='CERBERUZ memisahkan thermoplastics dan bahan lain, menggiling,mencampur,lalu injection molding. Busa termoset jadi filler, bukan dilelehkan seperti termoplastik. Menang Prototype dan Digital Twin fase2; belum di Bulan.',titles=['Di Bulan butuh suku\ncadang. Sampah dipakai?','01 / Kemasan dipilah.\nLalu digiling halus.','02 / Plastik meleleh.\nBahan lain jadi pengisi.','03 / Masuk cetakan.\nKeluar komponen.','Dari limbah lokal.\nUntuk kebutuhan lokal.'],recap=[['PILAH','LIMBAH NONBIOLOGIS'],['CAMPUR','BAHAN KOMPOSIT'],['CETAK','KOMPONEN BERGUNA']],closing='Kemasan habis.\nBahannya belum habis.',pill='CERBERUZ • DEMONSTRASI 2026',lines=[['Kamu di Bulan, butuh suku cadang.','Sampah kemasan bisa membantu?'],['Kita ikuti konsep CERBERUZ,','pemenang kompetisi daur ulang NASA.','Limbah nonbiologis dipilah, digiling halus, lalu dicampur.'],['Saat dipanaskan, plastik termoplastik meleleh,','sementara bahan lain menjadi pengisi.','Campuran komposit itu kemudian disuntikkan ke dalam cetakan.'],['Hasilnya bisa berupa komponen berguna.','Tapi demonstrasinya berlangsung di Bumi pada 2026,','bukan mesin yang sudah bekerja di permukaan Bulan.'],['Jadi, kemasan bukan cuma beban pengiriman.','Bahannya berpotensi dipakai kembali.','Benda apa yang paling masuk akal dibuat di lokasi?']],caption='CERBERUZ menggiling dan mencampur limbah nonbiologis menjadi bahan komposit untuk injection molding. Demonstrasi kompetisi2026 berlangsung di Bumi, belum mesin di Bulan. MIT melaporkan mekanismenya20Oktober2026. #Antariksa #DaurUlang')]
